1	package store
2	
3	import (
4		"encoding/json"
5		"sort"
6		"time"
7	)
8	
9	// CreateWebhookEndpoint stores an endpoint. The caller checks its URL and sets its secret.
10	func (s *Store) CreateWebhookEndpoint(ep WebhookEndpoint, now time.Time) (WebhookEndpoint, error) {
11		if len(ep.Events) == 0 {
12			return WebhookEndpoint{}, invalid("an endpoint needs at least one event type")
13		}
14		s.mu.Lock()
15		defer s.mu.Unlock()
16		if _, ok := s.orgs[ep.OrgID]; !ok {
17			return WebhookEndpoint{}, ErrNotFound
18		}
19		ep.ID = s.newID("we")
20		ep.CreatedAt = now.UTC()
21		ep.Events = append([]string(nil), ep.Events...)
22		s.endpoints[ep.ID] = ep
23		return copyEndpoint(ep), nil
24	}
25	
26	// WebhookEndpoint returns one of an organization's endpoints.
27	func (s *Store) WebhookEndpoint(orgID, id string) (WebhookEndpoint, bool) {
28		s.mu.Lock()
29		defer s.mu.Unlock()
30		ep, ok := s.endpoints[id]
31		if !ok || ep.OrgID != orgID {
32			return WebhookEndpoint{}, false
33		}
34		return copyEndpoint(ep), true
35	}
36	
37	// WebhookEndpoints returns an organization's endpoints, oldest first.
38	func (s *Store) WebhookEndpoints(orgID string) []WebhookEndpoint {
39		s.mu.Lock()
40		defer s.mu.Unlock()
41		out := []WebhookEndpoint{}
42		for _, ep := range s.endpoints {
43			if ep.OrgID == orgID {
44				out = append(out, copyEndpoint(ep))
45			}
46		}
47		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
48		return out
49	}
50	
51	// UpdateWebhookEndpoint changes an endpoint with f, which may refuse with an error.
52	func (s *Store) UpdateWebhookEndpoint(orgID, id string, f func(*WebhookEndpoint) error) (WebhookEndpoint, error) {
53		s.mu.Lock()
54		defer s.mu.Unlock()
55		old, ok := s.endpoints[id]
56		if !ok || old.OrgID != orgID {
57			return WebhookEndpoint{}, ErrNotFound
58		}
59		ep := copyEndpoint(old)
60		if err := f(&ep); err != nil {
61			return WebhookEndpoint{}, err
62		}
63		ep.ID, ep.OrgID, ep.CreatedAt = old.ID, old.OrgID, old.CreatedAt
64		if len(ep.Events) == 0 {
65			return WebhookEndpoint{}, invalid("an endpoint needs at least one event type")
66		}
67		s.endpoints[id] = copyEndpoint(ep)
68		return copyEndpoint(ep), nil
69	}
70	
71	// DeleteWebhookEndpoint removes an endpoint and its pending deliveries.
72	func (s *Store) DeleteWebhookEndpoint(id string) error {
73		s.mu.Lock()
74		defer s.mu.Unlock()
75		if _, ok := s.endpoints[id]; !ok {
76			return ErrNotFound
77		}
78		delete(s.endpoints, id)
79		for did, d := range s.delivs {
80			if d.EndpointID == id && d.Status == DeliveryPending {
81				delete(s.delivs, did)
82			}
83		}
84		return nil
85	}
86	
87	func copyEndpoint(ep WebhookEndpoint) WebhookEndpoint {
88		ep.Events = append([]string(nil), ep.Events...)
89		return ep
90	}
91	
92	// AddEvent records an event.
93	func (s *Store) AddEvent(orgID, typ string, data json.RawMessage, now time.Time) (Event, error) {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		if _, ok := s.orgs[orgID]; !ok {
97			return Event{}, ErrNotFound
98		}
99		e := Event{ID: s.newID("evt"), OrgID: orgID, Type: typ, Data: append(json.RawMessage(nil), data...), CreatedAt: now.UTC()}
100		s.events[e.ID] = e
101		return e, nil
102	}
103	
104	// Event returns one of an organization's events.
105	func (s *Store) Event(orgID, id string) (Event, bool) {
106		s.mu.Lock()
107		defer s.mu.Unlock()
108		e, ok := s.events[id]
109		if !ok || e.OrgID != orgID {
110			return Event{}, false
111		}
112		return e, true
113	}
114	
115	// EventByID returns an event of any organization (the webhook sender).
116	func (s *Store) EventByID(id string) (Event, bool) {
117		s.mu.Lock()
118		defer s.mu.Unlock()
119		e, ok := s.events[id]
120		return e, ok
121	}
122	
123	// Events returns an organization's events, oldest first, only those of one type when typ is set.
124	func (s *Store) Events(orgID, typ string) []Event {
125		s.mu.Lock()
126		defer s.mu.Unlock()
127		out := []Event{}
128		for _, e := range s.events {
129			if e.OrgID == orgID && (typ == "" || e.Type == typ) {
130				out = append(out, e)
131			}
132		}
133		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
134		return out
135	}
136	
137	// CreateDelivery queues an event for an endpoint.
138	func (s *Store) CreateDelivery(d Delivery, now time.Time) (Delivery, error) {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		ep, ok := s.endpoints[d.EndpointID]
142		if !ok || ep.OrgID != d.OrgID {
143			return Delivery{}, ErrNotFound
144		}
145		if e, ok := s.events[d.EventID]; !ok || e.OrgID != d.OrgID {
146			return Delivery{}, ErrNotFound
147		}
148		d.ID = s.newID("del")
149		d.CreatedAt = now.UTC()
150		if d.Status == "" {
151			d.Status = DeliveryPending
152		}
153		s.delivs[d.ID] = copyDelivery(d)
154		return copyDelivery(d), nil
155	}
156	
157	// Delivery returns a delivery of any organization (the webhook sender).
158	func (s *Store) Delivery(id string) (Delivery, bool) {
159		s.mu.Lock()
160		defer s.mu.Unlock()
161		d, ok := s.delivs[id]
162		return copyDelivery(d), ok
163	}
164	
165	// Deliveries returns an organization's deliveries to one endpoint, oldest first.
166	func (s *Store) Deliveries(orgID, endpointID string) []Delivery {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		out := []Delivery{}
170		for _, d := range s.delivs {
171			if d.OrgID == orgID && d.EndpointID == endpointID {
172				out = append(out, copyDelivery(d))
173			}
174		}
175		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
176		return out
177	}
178	
179	// DueDeliveries returns the pending deliveries of every organization whose next attempt is due by now, oldest first.
180	func (s *Store) DueDeliveries(now time.Time) []Delivery {
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		out := []Delivery{}
184		for _, d := range s.delivs {
185			if d.Status == DeliveryPending && d.NextAttemptAt != nil && !d.NextAttemptAt.After(now) {
186				out = append(out, copyDelivery(d))
187			}
188		}
189		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
190		return out
191	}
192	
193	// UpdateDelivery changes a delivery with f.
194	func (s *Store) UpdateDelivery(id string, f func(*Delivery) error) (Delivery, error) {
195		s.mu.Lock()
196		defer s.mu.Unlock()
197		old, ok := s.delivs[id]
198		if !ok {
199			return Delivery{}, ErrNotFound
200		}
201		d := copyDelivery(old)
202		if err := f(&d); err != nil {
203			return Delivery{}, err
204		}
205		d.ID, d.OrgID, d.EndpointID, d.EventID, d.CreatedAt = old.ID, old.OrgID, old.EndpointID, old.EventID, old.CreatedAt
206		s.delivs[id] = copyDelivery(d)
207		return copyDelivery(d), nil
208	}
209	
210	func copyDelivery(d Delivery) Delivery {
211		for _, p := range []**time.Time{&d.NextAttemptAt, &d.LastAttemptAt} {
212			if *p != nil {
213				t := **p
214				*p = &t
215			}
216		}
217		return d
218	}
