// retryDelays are the waits after each failed attempt: after the first failure the next attempt is a minute later, after
// the second 5 minutes later, and so on. A delivery that fails the attempt after the last wait is failed for good.
var retryDelays = []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}

// maxAttempts is how many attempts a delivery gets before it is failed for good.
var maxAttempts = len(retryDelays) + 1

// noticeInterval is the least time between two emails to the owners about one endpoint's failing deliveries.
const noticeInterval = 24 * time.Hour

// RunDue attempts every delivery that is due and returns how many attempts it made. A failed attempt leaves the delivery
