func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		if errText == "" {
			d.Status = store.DeliverySucceeded
		} else {
			d.Status = store.DeliveryFailed
		}
		return nil
	})
}

args.new_string:
// deliver makes one attempt at a due delivery and records the result. It reports whether it made an attempt: a delivery
// that cannot be sent, because its endpoint is disabled or its event is gone, is failed for good without one.
func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
	cur, ok := s.store.Delivery(d.ID)
	if !ok || cur.Status != store.DeliveryPending {
		return false
	}
	d = cur
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	if !ok || !ep.Enabled {
		s.failForGood(d, "the endpoint is disabled or was deleted")
		return false
	}
	e, ok := s.store.EventByID(d.EventID)
	if !ok {
		s.failForGood(d, "the event no longer exists")
		return false
	}
	code, errText := s.send(ctx, ep, e)
	now := s.clock.Now()
	gone := code == http.StatusGone
	attempts := d.Attempts + 1
	var next *time.Time
	st := store.DeliveryPending
	switch {
	case errText == "":
		st = store.DeliverySucceeded
	case gone || attempts >= maxAttempts:
		st = store.DeliveryFailed
	default:
		t := now.Add(retryDelays[attempts-1])
		next = &t
	}
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts = attempts
		d.LastAttemptAt = &now
		d.NextAttemptAt = next
		d.ResponseStatus = code
		d.Error = errText
		d.Status = st
		return nil
	})
	switch {
	case gone:
		// The receiver is gone: disable the endpoint and fail its other pending deliveries, so none of them is sent.
		_, _ = s.store.UpdateWebhookEndpoint(d.OrgID, ep.ID, func(w *store.WebhookEndpoint) error {
			w.Enabled = false
			w.DisabledReason = "gone"
			return nil
		})
		s.failPending(d.OrgID, ep.ID)
	case st == store.DeliveryFailed:
		s.notifyOwners(ctx, ep, now)
	}
	return true
}

// failForGood fails a delivery that will not be attempted again, without an attempt.
func (s *Service) failForGood(d store.Delivery, why string) {
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Status = store.DeliveryFailed
		d.NextAttemptAt = nil
		d.Error = why
		return nil
	})
}

