// giveUp runs the endpoint's deliveries through their retries, moving the clock to each next attempt, until none is pending.
func giveUp(t *testing.T, e *apitest.Env, orgID, endpointID string) {
	t.Helper()
	for {
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
		var next *time.Time
		for _, d := range e.Store.Deliveries(orgID, endpointID) {
			if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
				next = d.NextAttemptAt
			}
		}
		if next == nil {
			return
		}
		e.Clock.Set(*next)
	}
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/retry", Events: []string{"*"}, Secret: "whsec_r", Enabled: true}, e.Clock.Now())
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusServiceUnavailable, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	waits := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
		if d.Attempts != attempt || d.ResponseStatus != http.StatusServiceUnavailable || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("attempt %d: delivery = %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the 7th attempt: delivery = %+v", d)
			}
