			}
			break
		}
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(waits[attempt-1])) {
			t.Fatalf("attempt %d: delivery = %+v, want the next attempt %s later", attempt, d, waits[attempt-1])
