		t.Skip("waits the 10 second timeout")
	}
	e := apitest.New(t)
	ctx := context.Background()
	svc := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: hangingDoer{}, Resolver: e.DNS})
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/slow", Events: []string{"*"}, Secret: "whsec_s", Enabled: true}, e.Clock.Now())
	if err := svc.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	if n, err := svc.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	if took := time.Since(start); took < 10*time.Second || took > 15*time.Second {
		t.Fatalf("the attempt took %s, want about 10 seconds", took)
	}
	if d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]; d.Status != store.DeliveryPending || d.Error == "" || d.NextAttemptAt == nil {
		t.Fatalf("a slow delivery = %+v, want pending for a retry", d)
	}
}

