124	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
125	// type. The deliveries are sent by RunDue.
126	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
127		raw, err := json.Marshal(data)
128		if err != nil {
129			return err
130		}
131		now := s.clock.Now()
132		e, err := s.store.AddEvent(orgID, eventType, raw, now)
133		if err != nil {
134			return err
135		}
136		for _, ep := range s.store.WebhookEndpoints(orgID) {
137			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
138				continue
139			}
140			next := now
141			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
142				return err
143			}
144		}
145		return nil
146	}
147	
148	// retryDelays are the waits after each failed attempt: after the first failure the next attempt is a minute later, after
149	// the second 5 minutes later, and so on. A delivery that fails the attempt after the last wait is failed for good.
150	var retryDelays = []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
151	
152	// maxAttempts is how many attempts a delivery gets before it is failed for good.
153	var maxAttempts = len(retryDelays) + 1
154	
155	// noticeInterval is the least time between two emails to the owners about one endpoint's failing deliveries.
156	const noticeInterval = 24 * time.Hour
157	
158	// RunDue attempts every delivery that is due and returns how many attempts it made. A failed attempt leaves the delivery
159	// pending until its next attempt (see retryDelays); a 410 Gone answer or the last attempt fails it for good.
160	func (s *Service) RunDue(ctx context.Context) (int, error) {
161		n := 0
162		for _, d := range s.store.DueDeliveries(s.clock.Now()) {
163			if err := ctx.Err(); err != nil {
164				return n, err
165			}
166			if s.deliver(ctx, d) {
167				n++
168			}
169		}
170		return n, nil
171	}
172	
173	// Body is what a delivery POSTs.
174	type Body struct {
175		ID        string          `json:"id"`
176		Type      string          `json:"type"`
177		CreatedAt time.Time       `json:"created_at"`
178		Data      json.RawMessage `json:"data"`
179	}
180	
181	// deliver makes one attempt at a due delivery and records the result. It reports whether it made an attempt: a delivery
182	// that cannot be sent, because its endpoint is disabled or its event is gone, is failed for good without one.
183	func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
184		cur, ok := s.store.Delivery(d.ID)
185		if !ok || cur.Status != store.DeliveryPending {
186			return false
187		}
188		d = cur
189		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
190		if !ok || !ep.Enabled {
191			s.failForGood(d, "the endpoint is disabled or was deleted")
192			return false
193		}
194		e, ok := s.store.EventByID(d.EventID)
195		if !ok {
196			s.failForGood(d, "the event no longer exists")
197			return false
198		}
199		code, errText := s.send(ctx, ep, e)
200		now := s.clock.Now()
201		gone := code == http.StatusGone
202		attempts := d.Attempts + 1
203		var next *time.Time
204		st := store.DeliveryPending
205		switch {
206		case errText == "":
207			st = store.DeliverySucceeded
208		case gone || attempts >= maxAttempts:
209			st = store.DeliveryFailed
210		default:
211			t := now.Add(retryDelays[attempts-1])
212			next = &t
213		}
214		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
215			d.Attempts = attempts
216			d.LastAttemptAt = &now
217			d.NextAttemptAt = next
218			d.ResponseStatus = code
219			d.Error = errText
220			d.Status = st
221			return nil
222		})
223		switch {
224		case gone:
225			// The receiver is gone: disable the endpoint and fail its other pending deliveries, so none of them is sent.
226			_, _ = s.store.UpdateWebhookEndpoint(d.OrgID, ep.ID, func(w *store.WebhookEndpoint) error {
227				w.Enabled = false
228				w.DisabledReason = "gone"
229				return nil
230			})
231			s.failPending(d.OrgID, ep.ID)
232		case st == store.DeliveryFailed:
233			s.notifyOwners(ctx, ep, now)
234		}
235		return true
236	}
