238	// failForGood fails a delivery that will not be attempted again, without an attempt.
239	func (s *Service) failForGood(d store.Delivery, why string) {
240		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
241			d.Status = store.DeliveryFailed
242			d.NextAttemptAt = nil
243			d.Error = why
244			return nil
245		})
246	}
247	
248	// failPending fails the endpoint's pending deliveries for good.
249	func (s *Service) failPending(orgID, endpointID string) {
250		for _, d := range s.store.Deliveries(orgID, endpointID) {
251			if d.Status == store.DeliveryPending {
252				s.failForGood(d, "the endpoint is disabled or was deleted")
253			}
254		}
255	}
