280	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
281	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
282		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
283		if err != nil {
284			return 0, err.Error()
285		}
286		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
287		defer cancel()
288		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
289		if err != nil {
290			return 0, err.Error()
291		}
292		req.Header.Set("Content-Type", "application/json")
293		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
294		req.Header.Set("Tally-Event-Id", e.ID)
295		req.Header.Set("Tally-Event-Type", e.Type)
296		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
297		resp, err := s.doer.Do(req)
298		if err != nil {
299			return 0, err.Error()
300		}
301		defer resp.Body.Close()
