181	// deliver makes one attempt at a due delivery and records the result. It reports whether it made an attempt: a delivery
182	// that cannot be sent, because its endpoint is disabled or its event is gone, is failed for good without one.
183	func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
184		cur, ok := s.store.Delivery(d.ID)
185		if !ok || cur.Status != store.DeliveryPending {
186			return false
187		}
188		d = cur
189		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
190		if !ok || !ep.Enabled {
191			s.failForGood(d, "the endpoint is disabled or was deleted")
192			return false
193		}
194		e, ok := s.store.EventByID(d.EventID)
195		if !ok {
196			s.failForGood(d, "the event no longer exists")
197			return false
198		}
199		code, errText := s.send(ctx, ep, e)
200		now := s.clock.Now()
201		gone := code == http.StatusGone
202		attempts := d.Attempts + 1
203		var next *time.Time
204		st := store.DeliveryPending
205		switch {
206		case errText == "":
207			st = store.DeliverySucceeded
208		case gone || attempts >= maxAttempts:
209			st = store.DeliveryFailed
210		default:
211			t := now.Add(retryDelays[attempts-1])
212			next = &t
213		}
214		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
215			d.Attempts = attempts
216			d.LastAttemptAt = &now
217			d.NextAttemptAt = next
218			d.ResponseStatus = code
219			d.Error = errText
220			d.Status = st
221			return nil
222		})
223		switch {
224		case gone:
225			// The receiver is gone: disable the endpoint and fail its other pending deliveries, so none of them is sent.
226			_, _ = s.store.UpdateWebhookEndpoint(d.OrgID, ep.ID, func(w *store.WebhookEndpoint) error {
227				w.Enabled = false
228				w.DisabledReason = "gone"
229				return nil
230			})
231			s.failPending(d.OrgID, ep.ID)
232		case st == store.DeliveryFailed:
233			s.notifyOwners(ctx, ep, now)
234		}
235		return true
236	}
