238	// failForGood fails a delivery that will not be attempted again, without an attempt.
239	func (s *Service) failForGood(d store.Delivery, why string) {
240		_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
241			d.Status = store.DeliveryFailed
242			d.NextAttemptAt = nil
243			d.Error = why
244			return nil
245		})
246	}
