257	// notifyOwners emails every owner of the endpoint's organization that the endpoint is failing, unless they were emailed
258	// about it within noticeInterval.
259	func (s *Service) notifyOwners(ctx context.Context, ep store.WebhookEndpoint, now time.Time) {
260		if s.mail == nil || (!ep.FailureNoticeAt.IsZero() && now.Before(ep.FailureNoticeAt.Add(noticeInterval))) {
261			return
262		}
263		_, _ = s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(w *store.WebhookEndpoint) error {
264			w.FailureNoticeAt = now
265			return nil
266		})
267		for _, m := range s.store.Members(ep.OrgID) {
268			u, ok := s.store.User(m.UserID)
269			if m.Role != store.RoleOwner || !ok {
270				continue
271			}
272			_ = s.mail.Send(ctx, mail.Message{
273				To:      u.Email,
274				Subject: "Webhook endpoint failing: " + ep.URL,
275				Body:    fmt.Sprintf("Deliveries to %s failed %d times, so Tally has given them up. Check that the endpoint answers with a 2xx status within 10 seconds.\n", ep.URL, maxAttempts),
276			})
277		}
278	}
